namespace Braemac.Factory {
 [Serializable] public class ThreeFrame{public string station_id,frame_id,image;public int[] roi=new[]{48,48,160,160};}
 [Serializable] public class ThreeBatch{public string contract="gts.three-frame/1",line_id="Line01",session_id,bottle_id,batch_id,capture_utc,product;public double source_time;public int target_count=1;public bool observations_available=true;public ThreeFrame[] frames;}
 [Serializable] public class ThreeResult{public string line_id,session_id,bottle_id,batch_id,station_id,frame_id,capture_utc,completed_utc,decision,wording,reason,device,backend,model_sha256,crop_url,product;public double score,age_seconds,end_to_end_ms,queue_ms,preprocess_ms,transfer_ms,inference_ms,gpu_elapsed_ms;public bool historical;}
 [Serializable] public class ThreeState{public string selected_device,actual_device,gpu_status,status,assistant_state,assistant_text,assistant_event_id,quality_summary;public int queued,completed,dropped,stale,missed_deadlines,queue_depth,explanation_calls;public double elapsed_seconds,inspection_rate,host_cpu_percent,service_cpu_percent,service_rss_mb,native_cpu_percent,native_rss_mb,gpu_busy_percent,available_memory_gb,temperature_c,monitor_ms;public ThreeResult[] results,events;}
 [Serializable] public class ThreeDatasetItem{public string id,group,split,product;public int condition,cap_condition,fill_condition,label_condition,adjacent,quality_mode,seed;public float light,camera_x,camera_y,rotation,fill,offset,tilt;}
