 public sealed class ThreeStationInspection:MonoBehaviour {
  StationCameraSet cameraConfig;FactoryApp app;Camera[] cameras=new Camera[3];RenderTexture[] targets=new RenderTexture[3];Texture2D[] readers=new Texture2D[3];Light light;GameObject cover;
  readonly string[] stations={"cap","fill","label"};readonly HashSet<int> seen=new HashSet<int>();readonly Dictionary<string,Texture2D> textures=new Dictionary<string,Texture2D>();readonly HashSet<string> loading=new HashSet<string>();readonly Queue<string> textureOrder=new Queue<string>();
  ThreeState state=new ThreeState{status="Connecting",selected_device="cpu",actual_device="unavailable",assistant_state="idle",gpu_busy_percent=-1,temperature_c=-1};string endpoint,dataset,session,view="Combined",lastView="",selectedEvent="",notice="",visualScenario="Healthy";double nextCapture,nextPoll,mixAt,auditAt;bool sending,polling,disabled;int captures,dropped;GUIStyle title,text,small,button,reviewButton,neutralButton,selectedButton;Texture2D white,background,buttonBackground;Vector2 scroll;ThreeResult selected;readonly Queue<float> frameTimes=new Queue<float>();float fp50,fp95,fp99;double frameStatsAt;
  void Start(){app=GetComponent<FactoryApp>();cameraConfig=JsonUtility.FromJson<StationCameraSet>(File.ReadAllText(FactoryApp.Argument("--stage3-camera-config",Path.Combine(Application.streamingAssetsPath,"stage3-cameras.json"))));if(cameraConfig.frame_width!=256||cameraConfig.frame_height!=256||cameraConfig.crop_width!=160||cameraConfig.crop_height!=160||cameraConfig.stations.Length!=3)throw new Exception("Frozen Stage3 model dimensions required");endpoint=FactoryApp.Argument("--stage3-endpoint","http://127.0.0.1:8820");if(new Uri(endpoint).Host!="127.0.0.1")throw new Exception("Stage3 requires loopback");dataset=FactoryApp.Argument("--stage3-dataset");disabled=FactoryApp.Argument("--inspection-disabled","false")=="true";session=app.Plc.Mapping.Frame.session;
   light=new GameObject("Stage3 controlled inspection light").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.2f;light.color=Color.white;light.cullingMask=1<<10;light.transform.rotation=Quaternion.Euler(12,-10,0);
   cover=GameObject.CreatePrimitive(PrimitiveType.Cube);cover.layer=10;cover.GetComponent<Collider>().enabled=false;cover.GetComponent<Renderer>().material=new Material(Shader.Find("Standard"));cover.GetComponent<Renderer>().material.color=new Color(.18f,.18f,.18f);cover.transform.localScale=new Vector3(.7f,1.3f,.03f);cover.SetActive(false);
   for(int i=0;i<3;i++){var c=new GameObject("Stage3 "+stations[i]+" camera").AddComponent<Camera>();c.enabled=false;c.cullingMask=1<<10;c.orthographic=true;c.orthographicSize=cameraConfig.stations[i].orthographic_size;c.nearClipPlane=.02f;c.farClipPlane=4;c.backgroundColor=new Color(.72f,.75f,.76f);c.clearFlags=CameraClearFlags.SolidColor;targets[i]=new RenderTexture(256,256,24);c.targetTexture=targets[i];cameras[i]=c;readers[i]=new Texture2D(256,256,TextureFormat.RGB24,false);Position(i,0,0);}
   if(dataset!=""){app.RemoteAction("pause","");StartCoroutine(Dataset());}else StartCoroutine(Command("/session","{\"session_id\":\""+session+"\"}"));
  }
  void Position(int i,float dx,float dy){float y=1.01f+cameraConfig.stations[i].center_y;cameras[i].transform.position=new Vector3(cameraConfig.trigger_x+dx,y+dy,-.8f);cameras[i].transform.LookAt(new Vector3(cameraConfig.trigger_x,y,0));}
  void Layer(GameObject root,int layer){foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=layer;}
  byte[] Read(int i){cameras[i].Render();var old=RenderTexture.active;RenderTexture.active=targets[i];readers[i].ReadPixels(new Rect(0,0,256,256),0,0);readers[i].Apply();RenderTexture.active=old;return readers[i].EncodeToPNG();}
  void Update(){if(app==null||dataset!="")return;if(Input.GetKeyDown(KeyCode.Alpha1))view="Machine data";if(Input.GetKeyDown(KeyCode.Alpha2))view="Digital twin";if(Input.GetKeyDown(KeyCode.Alpha3))view="Combined";if(FactoryApp.Argument("--product-mix","false")=="true"&&Time.realtimeSinceStartupAsDouble>=mixAt){mixAt=Time.realtimeSinceStartupAsDouble+20;app.SelectProduct(new[]{"LAGER","IPA","STOUT"}[(int)(Time.realtimeSinceStartupAsDouble/20)%3]);}frameTimes.Enqueue(Time.unscaledDeltaTime*1000);if(frameTimes.Count>300)frameTimes.Dequeue();if(Time.realtimeSinceStartupAsDouble>frameStatsAt){frameStatsAt=Time.realtimeSinceStartupAsDouble+1;var times=frameTimes.ToArray();Array.Sort(times);fp50=times[(times.Length-1)/2];fp95=times[(int)((times.Length-1)*.95)];fp99=times[(int)((times.Length-1)*.99)];}if(Time.realtimeSinceStartupAsDouble>=nextPoll&&!polling){nextPoll=Time.realtimeSinceStartupAsDouble+.5;StartCoroutine(Poll());}
   if(disabled||app.Paused||sending||Time.realtimeSinceStartupAsDouble<nextCapture)return;
   foreach(var b in app.Sim.Bottles)if(b.X>=cameraConfig.trigger_x-.02f&&b.X<=cameraConfig.trigger_x+.01f&&!seen.Contains(b.Id)&&app.Brewery.BottleById(b.Id)!=null){seen.Add(b.Id);nextCapture=Time.realtimeSinceStartupAsDouble+1.5;StartCoroutine(Capture(b));break;}
  }
  void LateUpdate(){if(app==null)return;if(FactoryApp.Argument("--stage3-audit","false")=="true"&&Time.realtimeSinceStartupAsDouble>=auditAt){auditAt=Time.realtimeSinceStartupAsDouble+.2;File.WriteAllText(Path.Combine(app.DataPath,"stage3-audit.json"),"{\"view\":\""+view+"\",\"session_id\":\""+session+"\",\"paused\":"+(app.Paused?"true":"false")+",\"product\":\""+app.PresentationProduct+"\",\"sim_time\":"+app.Sim.Time.ToString(System.Globalization.CultureInfo.InvariantCulture)+"}");}if(dataset=="")ApplyExample();bool data=view=="Machine data"||view=="Inspection"||view=="Failure review"||view=="Debug"||view=="Examples";app.MainCamera.cullingMask=data?0:~((1<<8)|(1<<10));app.MainCamera.rect=data?new Rect(0,0,1,1):new Rect(0,56f/1080,view=="Digital twin"?.755f:.64f,866f/1080);}
  IEnumerator Capture(Bottle b){sending=true;yield return new WaitForEndOfFrame();var visual=app.Brewery.BottleById(b.Id);if(visual==null){dropped++;sending=false;yield break;}
   var begin=DateTime.UtcNow;int count=0;foreach(var other in app.Sim.Bottles)if(Math.Abs(other.X-b.X)<.36f&&other.RejectTravel<.1)count++;
   var frames=new ThreeFrame[3];string batch=Guid.NewGuid().ToString("N");Layer(visual.Root,10);
   try{for(int i=0;i<3;i++){frames[i]=new ThreeFrame{station_id=stations[i],frame_id=Guid.NewGuid().ToString("N"),image=Convert.ToBase64String(Read(i)),roi=new[]{Mathf.Clamp(Mathf.RoundToInt(cameras[i].WorldToScreenPoint(visual.Root.transform.position+Vector3.up*cameraConfig.stations[i].center_y).x)-80,0,96),48,160,160}};}}
   finally{Layer(visual.Root,9);}
   var input=new ThreeBatch{line_id=cameraConfig.line_id,session_id=session,bottle_id=b.Id.ToString(),batch_id=batch,capture_utc=begin.ToString("o"),source_time=app.Sim.Time,product=app.PresentationProduct,target_count=count,frames=frames};captures++;
   using(var r=Post("/batch",JsonUtility.ToJson(input))){r.timeout=3;yield return r.SendWebRequest();if(r.result!=UnityWebRequest.Result.Success){dropped++;notice="Capture not accepted: "+r.downloadHandler.text;}}
   sending=false;
  }
  UnityWebRequest Post(string path,string json){var r=new UnityWebRequest(endpoint+path,"POST");r.uploadHandler=new UploadHandlerRaw(Encoding.UTF8.GetBytes(json));r.downloadHandler=new DownloadHandlerBuffer();r.SetRequestHeader("Content-Type","application/json");return r;}
  IEnumerator Command(string path,string json){using(var r=Post(path,json)){r.timeout=3;yield return r.SendWebRequest();notice=r.result==UnityWebRequest.Result.Success?"Request accepted":r.downloadHandler.text;}}
  IEnumerator Poll(){polling=true;using(var r=UnityWebRequest.Get(endpoint+"/state?session_id="+session)){r.timeout=2;yield return r.SendWebRequest();if(r.result==UnityWebRequest.Result.Success){state=JsonUtility.FromJson<ThreeState>(r.downloadHandler.text);if(state.results!=null)foreach(var result in state.results)Load(result);if(selected!=null)Load(selected);}else{notice="Inspection unavailable — no current pass";state.status="unavailable";state.actual_device="unavailable";state.host_cpu_percent=state.service_cpu_percent=state.service_rss_mb=state.native_cpu_percent=state.native_rss_mb=state.gpu_busy_percent=state.temperature_c=state.available_memory_gb=state.monitor_ms=-1;}}polling=false;}
  void Load(ThreeResult r){if(!textures.ContainsKey(r.frame_id)&&loading.Add(r.frame_id))StartCoroutine(GetImage(r));}
  IEnumerator GetImage(ThreeResult result){using(var r=UnityWebRequest.Get(endpoint+result.crop_url)){r.timeout=2;yield return r.SendWebRequest();if(r.result==UnityWebRequest.Result.Success){var texture=new Texture2D(2,2);if(texture.LoadImage(r.downloadHandler.data)){textures[result.frame_id]=texture;textureOrder.Enqueue(result.frame_id);while(textureOrder.Count>32){string id=textureOrder.Dequeue();Destroy(textures[id]);textures.Remove(id);}}else Destroy(texture);}}loading.Remove(result.frame_id);}
  public void NewSession(){if(app==null)return;session=app.Plc.Mapping.Frame.session;seen.Clear();selected=null;selectedEvent="";visualScenario="Healthy";StartCoroutine(Command("/session","{\"session_id\":\""+session+"\"}"));}
  // Presenter-only visual fixtures. The classifier receives rendered pixels, never these labels.
  void ApplyExample(){foreach(var b in app.Sim.Bottles){if(b.Stage<4)continue;var v=app.Brewery.BottleById(b.Id);if(v==null)continue;var label=v.Root.transform.Find("Readable wrap label");if(visualScenario=="Cap missing")v.Cap.SetActive(false);if(visualScenario=="Cap displaced"){v.Cap.SetActive(true);v.Cap.transform.localPosition=new Vector3(.08f,.76f,0);v.Cap.transform.localRotation=Quaternion.Euler(0,0,20);}
    if(visualScenario=="Underfill"||visualScenario=="Overfill"){float f=visualScenario=="Underfill"?.84f:1.14f;v.Fluid.transform.localScale=new Vector3(.305f,.43f*f/2,.305f);v.Fluid.transform.localPosition=new Vector3(0,.04f+.43f*f/2,0);}
    label.gameObject.SetActive(visualScenario!="Label missing");label.localPosition=new Vector3(0,visualScenario=="Label tilted"?.33f:.27f,0);label.localRotation=Quaternion.Euler(0,0,visualScenario=="Label tilted"?22:0);
   }cover.SetActive(visualScenario=="Poor image");cover.transform.position=new Vector3(3,1.45f,-.3f);}
  IEnumerator Dataset(){yield return new WaitForEndOfFrame();var plan=JsonUtility.FromJson<ThreeDatasetPlan>(File.ReadAllText(Path.Combine(dataset,"capture-plan.json")));Directory.CreateDirectory(Path.Combine(dataset,"frames"));BottleVisual v=null;foreach(var b in app.Sim.Bottles){v=app.Brewery.BottleById(b.Id);if(v!=null)break;}if(v==null)throw new Exception("Brewery target unavailable");
   foreach(var item in plan.items){yield return new WaitForEndOfFrame();app.SelectProduct(item.product);v.Root.transform.position=new Vector3(3+(item.adjacent-.5f)*.006f,1.01f,0);v.Root.transform.rotation=Quaternion.Euler(0,item.rotation,0);v.Cap.SetActive(item.cap_condition!=1);v.Cap.transform.localPosition=new Vector3(item.cap_condition==2?item.offset:0,.76f,0);v.Cap.transform.localRotation=Quaternion.Euler(0,0,item.cap_condition==2?item.tilt:0);float h=.43f*item.fill;v.Fluid.SetActive(true);v.Fluid.transform.localScale=new Vector3(.305f,h/2,.305f);v.Fluid.transform.localPosition=new Vector3(0,.04f+h/2,0);var label=v.Root.transform.Find("Readable wrap label");label.gameObject.SetActive(item.label_condition!=1);label.localPosition=new Vector3(0,item.label_condition==2?.33f:.27f,0);label.localRotation=Quaternion.Euler(0,0,item.label_condition==2?item.tilt:0);light.intensity=item.light;cover.SetActive(false);cover.transform.position=new Vector3(3,1.45f,-.3f);Layer(v.Root,10);
    try{for(int i=0;i<3;i++){cover.SetActive(new[]{item.cap_condition,item.fill_condition,item.label_condition}[i]==3&&item.quality_mode==0);Position(i,item.camera_x,item.camera_y);File.WriteAllBytes(Path.Combine(dataset,"frames",item.id+"-"+stations[i]+".png"),Read(i));}}finally{Layer(v.Root,9);}
   }Debug.Log("STAGE3_CAPTURE_COMPLETE "+plan.items.Length*3);Application.Quit();}
  void Styles(){if(title!=null)return;white=new Texture2D(1,1);white.SetPixel(0,0,Color.white);white.Apply();background=new Texture2D(1,1);background.SetPixel(0,0,new Color(.92f,.94f,.95f));background.Apply();buttonBackground=new Texture2D(1,1);buttonBackground.SetPixel(0,0,new Color(.17f,.25f,.32f));buttonBackground.Apply();text=new GUIStyle(GUI.skin.label){fontSize=19,wordWrap=true,normal={textColor=new Color(.08f,.14f,.19f)}};small=new GUIStyle(text){fontSize=16};title=new GUIStyle(text){fontSize=27,fontStyle=FontStyle.Bold};button=new GUIStyle(GUI.skin.button){padding=new RectOffset(3,3,2,2),fontSize=17,fixedHeight=0,normal={textColor=Color.white,background=buttonBackground},hover={textColor=Color.white,background=buttonBackground},active={textColor=Color.white,background=buttonBackground}};neutralButton=new GUIStyle(button);selectedButton=new GUIStyle(button);foreach(var style in new[]{neutralButton,selectedButton}){style.normal.background=style.hover.background=style.active.background=white;style.normal.textColor=style.hover.textColor=style.active.textColor=style==selectedButton?Color.white:new Color(.08f,.18f,.23f);}reviewButton=new GUIStyle(button){wordWrap=true,fixedHeight=75,fontSize=16,alignment=TextAnchor.MiddleLeft,padding=new RectOffset(8,8,4,4)};}
  void Panel(Rect r){GUI.DrawTexture(r,white);}
  bool Button(Rect r,string label,bool selected=false){Color old=GUI.color;GUI.color=selected?new Color(.04f,.44f,.48f):new Color(.87f,.91f,.93f);GUI.DrawTexture(r,white);GUI.color=old;var style=selected?selectedButton:neutralButton;GUI.backgroundColor=selected?new Color(.04f,.44f,.48f):new Color(.87f,.91f,.93f);bool value=GUI.Button(r,label,style);GUI.backgroundColor=Color.white;return value;}
  ThreeResult Current(string station){if(state.results!=null)foreach(var r in state.results)if(r.station_id==station)return r;return null;}
  string Status(ThreeResult r){if(r==null)return "Awaiting image";if(state.status=="unavailable")return "Unable to assess — service offline";if(r.session_id!=session||app.Paused||r.age_seconds>3)return "Historical / not current";return r.wording;}
  void Card(string station,Rect rect,bool large){Panel(rect);var r=Current(station);Color oldColor=GUI.color;GUI.color=r==null||r.decision=="uncertain"?new Color(.9f,.61f,.15f):r.decision=="aligned"||r.decision=="within_range"?new Color(.12f,.50f,.31f):new Color(.77f,.19f,.18f);GUI.DrawTexture(new Rect(rect.x,rect.y,rect.width,5),white);GUI.color=oldColor;GUI.Label(new Rect(rect.x+14,rect.y+8,rect.width-28,40),station.ToUpperInvariant()+"  /  "+Status(r),text);float size=large?300:155;if(r!=null&&textures.ContainsKey(r.frame_id))GUI.DrawTexture(new Rect(rect.x+16,rect.y+58,size,size),textures[r.frame_id],ScaleMode.ScaleToFit);else GUI.Label(new Rect(rect.x+16,rect.y+60,size,size),"No camera evidence",small);
   float x=large?rect.x+16:rect.x+186,y=large?rect.y+370:rect.y+58;
   GUI.Label(new Rect(x,y,rect.width-(x-rect.x)-18,large?160:150),r==null?"Simulator-assisted association. Awaiting one target. No inspection is a pass without evidence.":"Bottle "+r.bottle_id+" • "+r.product+"\n"+r.device+" / "+r.backend+"\nAge "+r.age_seconds.ToString("0.0")+" s • "+r.end_to_end_ms.ToString("0.0")+" ms\n"+r.reason,small);
   if(r!=null&&Button(new Rect(rect.x+14,rect.yMax-46,rect.width-28,36),"Review this evidence")){selected=r;selectedEvent=r.frame_id;view="Failure review";Load(r);}
  }
  string PreviewStatus(ThreeResult r){if(r==null||state.status=="unavailable"||r.session_id!=session||app.Paused||r.age_seconds>3)return Status(r);switch(r.decision){case "aligned":return "Visually present / aligned";case "missing":return "Visually missing";case "displaced":return "Visually displaced";case "within_range":return "Visible level within demo range";case "underfilled":return "Visible level low";case "overfilled":return "Visible level high";case "misaligned":return "Visually misaligned";default:return "Unable to assess";}}
  void Preview(string station,Rect rect){Panel(rect);var r=Current(station);bool current=r!=null&&state.status!="unavailable"&&r.session_id==session&&!app.Paused&&r.age_seconds<=3;Color old=GUI.color;GUI.color=!current||r.decision=="uncertain"?new Color(.9f,.61f,.15f):r.decision=="aligned"||r.decision=="within_range"?new Color(.12f,.50f,.31f):new Color(.77f,.19f,.18f);GUI.DrawTexture(new Rect(rect.x,rect.y,4,rect.height),white);GUI.color=old;
   GUI.Label(new Rect(rect.x+12,rect.y+8,rect.width-24,27),station.ToUpperInvariant()+" • "+PreviewStatus(r),small);
   if(r!=null&&textures.ContainsKey(r.frame_id))GUI.DrawTexture(new Rect(rect.x+12,rect.y+42,92,92),textures[r.frame_id],ScaleMode.ScaleToFit);else GUI.Label(new Rect(rect.x+12,rect.y+43,92,92),"Awaiting image",small);
   GUI.Label(new Rect(rect.x+116,rect.y+43,rect.width-130,57),r==null?"No evidence yet.\nNo image is not a pass.":"Bottle "+r.bottle_id+" • "+r.device+"\nAge "+r.age_seconds.ToString("0.0")+"s • "+r.end_to_end_ms.ToString("0.0")+"ms",small);
   if(r!=null&&Button(new Rect(rect.x+116,rect.y+104,rect.width-130,30),"Open evidence")){selected=r;selectedEvent=r.frame_id;view="Failure review";Load(r);}
  }
  public void Draw(){if(app==null)return;Styles();if(view!=lastView){scroll=Vector2.zero;lastView=view;}GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1920f,Screen.height/1080f,1));Rect p=app.MainCamera.pixelRect;float left=p.x/Screen.width*1920,top=(Screen.height-p.yMax)/Screen.height*1080,bottom=(Screen.height-p.yMin)/Screen.height*1080,right=p.xMax/Screen.width*1920;
   GUI.DrawTexture(new Rect(0,0,1920,top),background);GUI.DrawTexture(new Rect(0,bottom,1920,1080-bottom),background);GUI.DrawTexture(new Rect(right,top,1920-right,bottom-top),background);
   Panel(new Rect(12,12,1896,140));GUI.Label(new Rect(28,18,1100,36),"BRAEMAC  /  GTS BREWERY",title);GUI.Label(new Rect(28,52,1250,22),"Synthetic line • simulator-assisted image association • visual appearance only",small);
   GUI.Label(new Rect(1320,22,565,45),"Vision: selected "+state.selected_device.ToUpperInvariant()+" / actual "+state.actual_device.ToUpperInvariant()+" • "+state.status,small);
   string[] modes={"Machine data","Digital twin","Combined","Inspection","Failure review","Debug"};for(int i=0;i<modes.Length;i++)if(Button(new Rect(28+i*170,78,160,32),modes[i],view==modes[i]))view=modes[i];
   if(Button(new Rect(1070,78,130,32),"Examples",view=="Examples"))view="Examples";
   GUI.Label(new Rect(1465,80,155,28),"Vision device",small);
   if(Button(new Rect(1630,78,115,32),"CPU",state.selected_device=="cpu"))StartCoroutine(Command("/device","{\"device\":\"cpu\"}"));if(Button(new Rect(1755,78,115,32),"GPU",state.selected_device=="gpu"))StartCoroutine(Command("/device","{\"device\":\"gpu\"}"));
   string[] actions={app.Paused?"Play":"Pause","Reset","Overview","Filler","Capper","Inspect"};for(int i=0;i<actions.Length;i++)if(Button(new Rect(28+i*145,116,135,30),actions[i])){if(i==0)app.TogglePause();if(i==1)app.ResetLine();if(i==2)app.Overview();if(i>=3)app.SelectPresentationView(i==3?"filler":i==4?"capper":"inspection");}
   GUI.Label(new Rect(1455,119,95,26),"Product",small);int n=0;foreach(string product in new[]{"LAGER","IPA","STOUT"})if(Button(new Rect(1550+n++*110,116,100,30),product,app.PresentationProduct==product))app.SelectProduct(product);
   if(view=="Examples"){Panel(new Rect(20,194,1880,665));GUI.Label(new Rect(45,215,1800,65),"PRESENTER ONLY • synthetic visual fixtures, not diagnosis or PLC writes",title);string[] examples={"Healthy","Cap missing","Cap displaced","Underfill","Overfill","Label missing","Label tilted","Poor image"};for(int i=0;i<examples.Length;i++)if(Button(new Rect(50,300+i*55,500,45),examples[i],visualScenario==examples[i]))visualScenario=examples[i];GUI.Label(new Rect(650,330,1100,240),"Fixtures change visible brewery geometry only. Inspect pixels and fixed results in Inspection. Cap/fill/label defects do not establish a cause. Reset returns to healthy. Existing B/C outfeed controls still operate the simulator. Space pause; R reset; F5–F8 views.",text);}
   else if(view=="Inspection"){for(int i=0;i<3;i++)Card(stations[i],new Rect(20+i*632,194,616,670),true);}
